import { useEffect, useMemo, useState } from "react";

interface User {
  id: string | number;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    const handle = setTimeout(() => {
      setDebouncedQuery(query);
    }, DEBOUNCE_MS);
    return () => clearTimeout(handle);
  }, [query]);

  useEffect(() => {
    if (!debouncedQuery) {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json();
      })
      .then((data: User[]) => {
        setUsers(data);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
        setUsers([]);
        setLoading(false);
      });

    return () => controller.abort();
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label>
          Sort by:{" "}
          <select
            value={sortField}
            onChange={(e) => setSortField(e.target.value as SortField)}
          >
            <option value="name">Name</option>
            <option value="email">Email</option>
          </select>
        </label>
      </div>

      {loading && <div role="status">Loading...</div>}
      {error && <div role="alert">Error: {error}</div>}

      {!loading && !error && debouncedQuery && (
        <div>{sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}</div>
      )}

      <ul>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            <span>{user.name}</span> &mdash; <span>{user.email}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const record = value as Record<string, unknown>;
  return (
    typeof record.id === "string" &&
    typeof record.name === "string" &&
    typeof record.email === "string"
  );
}

function parseUsers(data: unknown): User[] {
  if (!Array.isArray(data) || !data.every(isUser)) {
    throw new Error("Received malformed user data");
  }
  return data;
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    const term = query.trim();
    if (!term) {
      setUsers([]);
      setLoading(false);
      setError(null);
      return;
    }

    const controller = new AbortController();
    const timer = setTimeout(() => {
      setLoading(true);
      setError(null);

      fetch(`/api/users?q=${encodeURIComponent(term)}`, {
        signal: controller.signal,
      })
        .then((res) => {
          if (!res.ok) {
            throw new Error(`Request failed with status ${res.status}`);
          }
          return res.json();
        })
        .then((body: unknown) => {
          setUsers(parseUsers(body));
          setLoading(false);
        })
        .catch((err: unknown) => {
          if (err instanceof DOMException && err.name === "AbortError") {
            return;
          }
          setError(err instanceof Error ? err.message : "Failed to fetch users");
          setUsers([]);
          setLoading(false);
        });
    }, DEBOUNCE_MS);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label>
          Sort by:{" "}
          <select
            value={sortField}
            onChange={(e) => setSortField(e.target.value as SortField)}
          >
            <option value="name">Name</option>
            <option value="email">Email</option>
          </select>
        </label>
      </div>

      {loading && <div role="status">Loading...</div>}
      {error && <div role="alert">Error: {error}</div>}

      {!loading && !error && query.trim() !== "" && (
        <div>{sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}</div>
      )}

      <ul>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            {user.name} &lt;{user.email}&gt;
          </li>
        ))}
      </ul>
    </div>
  );
}

