import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;

async function fetchMetrics(signal: AbortSignal): Promise<Metric[]> {
  const res = await fetch("/api/metrics", { signal });
  if (!res.ok) {
    throw new Error(`Failed to load metrics: ${res.status}`);
  }
  return (await res.json()) as Metric[];
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [, setTick] = useState(0);

  const previousValuesRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    let cancelled = false;
    const controller = new AbortController();

    const refresh = async () => {
      if (document.hidden) return;
      try {
        const data = await fetchMetrics(controller.signal);
        if (cancelled) return;

        const previousValues = previousValuesRef.current;
        const nextChanged = new Set<string>();
        const nextValues = new Map<string, number>();
        for (const metric of data) {
          const prev = previousValues.get(metric.name);
          if (prev !== undefined && prev !== metric.value) {
            nextChanged.add(metric.name);
          }
          nextValues.set(metric.name, metric.value);
        }
        previousValuesRef.current = nextValues;

        setMetrics(data);
        setChangedNames(nextChanged);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (cancelled || controller.signal.aborted) return;
        setError(err instanceof Error ? err.message : "Failed to load metrics");
      }
    };

    void refresh();
    const intervalId = window.setInterval(refresh, POLL_INTERVAL_MS);

    const handleVisibilityChange = () => {
      if (!document.hidden) {
        void refresh();
      }
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      controller.abort();
      window.clearInterval(intervalId);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    const timerId = window.setInterval(() => setTick((t) => t + 1), 1_000);
    return () => window.clearInterval(timerId);
  }, []);

  const secondsAgo = lastUpdated
    ? Math.max(0, Math.round((Date.now() - lastUpdated.getTime()) / 1000))
    : null;

  return (
    <div className="metrics-panel">
      <div className="metrics-panel__header">
        <h2>Metrics</h2>
        <span className="metrics-panel__updated">
          {secondsAgo === null ? "Loading…" : `Last updated ${secondsAgo}s ago`}
        </span>
      </div>

      {error && <div className="metrics-panel__error">{error}</div>}

      <ul className="metrics-panel__list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? "metrics-panel__item metrics-panel__item--changed"
                : "metrics-panel__item"
            }
          >
            <span className="metrics-panel__name">{metric.name}</span>
            <span className="metrics-panel__value">
              {metric.value}
              {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, FormEvent } from "react";

interface FormValues {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormValues, string>>;

const INITIAL_VALUES: FormValues = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  if (!values.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!values.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(values.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!values.password) {
    errors.password = "Password is required.";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!values.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupResponse {
  id: string;
}

interface SignupErrorResponse {
  errors?: Record<string, string>;
}

export default function SignupForm() {
  const [values, setValues] = useState<FormValues>(INITIAL_VALUES);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);

  function updateField<K extends keyof FormValues>(field: K, value: FormValues[K]) {
    setValues((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitError(null);
    setAccountId(null);

    const clientErrors = validate(values);
    if (Object.keys(clientErrors).length > 0) {
      setErrors(clientErrors);
      return;
    }

    setSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: values.name,
          email: values.email,
          password: values.password,
          acceptTerms: values.acceptTerms,
        }),
      });

      if (!response.ok) {
        const data: SignupErrorResponse = await response.json().catch(() => ({}));
        if (data.errors) {
          setErrors(data.errors as FieldErrors);
        } else {
          setSubmitError("Something went wrong. Please try again.");
        }
        return;
      }

      const data: SignupResponse = await response.json();
      setAccountId(data.id);
      setValues(INITIAL_VALUES);
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  if (accountId) {
    return (
      <div role="status">
        <p>Account created successfully! Your account id is {accountId}.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={values.name}
          onChange={(e) => updateField("name", e.target.value)}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <span id="name-error">{errors.name}</span>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={values.email}
          onChange={(e) => updateField("email", e.target.value)}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <span id="email-error">{errors.email}</span>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={values.password}
          onChange={(e) => updateField("password", e.target.value)}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <span id="password-error">{errors.password}</span>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm password</label>
        <input
          id="confirmPassword"
          type="password"
          value={values.confirmPassword}
          onChange={(e) => updateField("confirmPassword", e.target.value)}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && <span id="confirmPassword-error">{errors.confirmPassword}</span>}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={values.acceptTerms}
            onChange={(e) => updateField("acceptTerms", e.target.checked)}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <span id="acceptTerms-error">{errors.acceptTerms}</span>}
      </div>

      {submitError && <p role="alert">{submitError}</p>}

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const REFRESH_INTERVAL_MS = 10_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    typeof candidate.unit === "string"
  );
}

function parseMetrics(data: unknown): Metric[] {
  if (!Array.isArray(data)) {
    throw new Error("Metrics response was not an array");
  }
  if (!data.every(isMetric)) {
    throw new Error("Metrics response contained malformed entries");
  }
  return data;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [secondsAgo, setSecondsAgo] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const previousValuesRef = useRef<Map<string, number>>(new Map());

  const fetchMetrics = useCallback(async () => {
    try {
      const response = await fetch("/api/metrics");
      if (!response.ok) {
        throw new Error(`Request failed with status ${response.status}`);
      }
      const data = parseMetrics(await response.json());

      const previousValues = previousValuesRef.current;
      const nextChanged = new Set<string>();
      const nextValues = new Map<string, number>();

      for (const metric of data) {
        nextValues.set(metric.name, metric.value);
        const previousValue = previousValues.get(metric.name);
        if (previousValue !== undefined && previousValue !== metric.value) {
          nextChanged.add(metric.name);
        }
      }

      previousValuesRef.current = nextValues;
      setMetrics(data);
      setChangedNames(nextChanged);
      setLastUpdated(new Date());
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load metrics");
    }
  }, []);

  useEffect(() => {
    fetchMetrics();

    let intervalId: ReturnType<typeof setInterval> | null = null;

    const startPolling = () => {
      if (intervalId === null) {
        intervalId = setInterval(fetchMetrics, REFRESH_INTERVAL_MS);
      }
    };

    const stopPolling = () => {
      if (intervalId !== null) {
        clearInterval(intervalId);
        intervalId = null;
      }
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        fetchMetrics();
        startPolling();
      }
    };

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      stopPolling();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [fetchMetrics]);

  useEffect(() => {
    if (!lastUpdated) {
      return;
    }

    const tick = () => {
      setSecondsAgo(Math.max(0, Math.round((Date.now() - lastUpdated.getTime()) / 1000)));
    };

    tick();
    const timerId = setInterval(tick, 1000);
    return () => clearInterval(timerId);
  }, [lastUpdated]);

  return (
    <div className="metrics-panel">
      <div className="metrics-panel__header">
        <h2>Metrics</h2>
        <span className="metrics-panel__timestamp">
          {lastUpdated ? `last updated ${secondsAgo} second${secondsAgo === 1 ? "" : "s"} ago` : "loading…"}
        </span>
      </div>

      {error && <div className="metrics-panel__error">{error}</div>}

      <ul className="metrics-panel__list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? "metrics-panel__item metrics-panel__item--changed"
                : "metrics-panel__item"
            }
          >
            <span className="metrics-panel__name">{metric.name}</span>
            <span className="metrics-panel__value">
              {metric.value}
              {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === 'string' &&
    typeof candidate.value === 'number' &&
    typeof candidate.unit === 'string'
  );
}

function isMetricArray(value: unknown): value is Metric[] {
  return Array.isArray(value) && value.every(isMetric);
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<number | null>(null);
  const [secondsAgo, setSecondsAgo] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const previousValues = useRef<Map<string, number>>(new Map());
  const abortControllerRef = useRef<AbortController | null>(null);
  const requestIdRef = useRef(0);

  const fetchMetrics = useCallback(async () => {
    abortControllerRef.current?.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;
    const requestId = ++requestIdRef.current;

    try {
      const response = await fetch('/api/metrics', { signal: controller.signal });
      if (!response.ok) {
        throw new Error(`Request failed with status ${response.status}`);
      }
      const data: unknown = await response.json();
      if (!isMetricArray(data)) {
        throw new Error('Received malformed metrics data');
      }
      if (requestId !== requestIdRef.current) {
        return;
      }

      const nextChanged = new Set<string>();
      for (const metric of data) {
        const previousValue = previousValues.current.get(metric.name);
        if (previousValue !== undefined && previousValue !== metric.value) {
          nextChanged.add(metric.name);
        }
      }
      previousValues.current = new Map(data.map((metric) => [metric.name, metric.value]));

      setMetrics(data);
      setChangedNames(nextChanged);
      setLastUpdated(Date.now());
      setError(null);
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') {
        return;
      }
      if (requestId !== requestIdRef.current) {
        return;
      }
      setError(err instanceof Error ? err.message : 'Failed to load metrics');
    }
  }, []);

  useEffect(() => {
    fetchMetrics();

    let intervalId: ReturnType<typeof setInterval> | null = null;

    const startPolling = () => {
      if (intervalId === null) {
        intervalId = setInterval(fetchMetrics, POLL_INTERVAL_MS);
      }
    };

    const stopPolling = () => {
      if (intervalId !== null) {
        clearInterval(intervalId);
        intervalId = null;
      }
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        fetchMetrics();
        startPolling();
      }
    };

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      stopPolling();
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      abortControllerRef.current?.abort();
    };
  }, [fetchMetrics]);

  useEffect(() => {
    if (lastUpdated === null) {
      return;
    }

    const updateSecondsAgo = () => {
      setSecondsAgo(Math.max(0, Math.round((Date.now() - lastUpdated) / 1000)));
    };

    updateSecondsAgo();
    const tickId = setInterval(updateSecondsAgo, 1000);
    return () => clearInterval(tickId);
  }, [lastUpdated]);

  return (
    <div className="metrics-panel">
      <div className="metrics-panel__header">
        <h2>Metrics</h2>
        <span className="metrics-panel__timestamp">
          {lastUpdated === null ? 'Loading…' : `Last updated ${secondsAgo} seconds ago`}
        </span>
      </div>
      {error !== null && <p className="metrics-panel__error">{error}</p>}
      <ul className="metrics-panel__list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? 'metrics-panel__item metrics-panel__item--changed'
                : 'metrics-panel__item'
            }
          >
            <span className="metrics-panel__name">{metric.name}</span>
            <span className="metrics-panel__value">
              {metric.value}
              {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, FormEvent } from "react";

interface FormValues {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormValues, string>>;

const initialValues: FormValues = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  if (!values.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!values.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_RE.test(values.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!values.password) {
    errors.password = "Password is required.";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!values.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupResponse {
  id: string;
}

interface SignupErrorResponse {
  errors?: Record<string, string>;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isSignupResponse(value: unknown): value is SignupResponse {
  return isRecord(value) && typeof value.id === "string";
}

function isFieldErrors(value: unknown): value is Record<string, string> {
  return (
    isRecord(value) &&
    Object.values(value).every((message) => typeof message === "string")
  );
}

function isSignupErrorResponse(value: unknown): value is SignupErrorResponse {
  if (!isRecord(value)) return false;
  if (value.errors === undefined) return true;
  return isFieldErrors(value.errors);
}

export default function SignupForm() {
  const [values, setValues] = useState<FormValues>(initialValues);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);

  function handleChange<K extends keyof FormValues>(field: K, value: FormValues[K]) {
    setValues((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();

    const validationErrors = validate(values);
    setErrors(validationErrors);
    setSubmitError(null);

    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: values.name,
          email: values.email,
          password: values.password,
          confirmPassword: values.confirmPassword,
          acceptTerms: values.acceptTerms,
        }),
      });

      if (!res.ok) {
        const errorBody: unknown = await res.json().catch(() => null);
        if (isSignupErrorResponse(errorBody) && errorBody.errors) {
          setErrors(errorBody.errors as FieldErrors);
        } else {
          setSubmitError("Signup failed. Please try again.");
        }
        return;
      }

      const successBody: unknown = await res.json().catch(() => null);
      if (!isSignupResponse(successBody)) {
        setSubmitError("Unexpected response from server. Please try again.");
        return;
      }
      setAccountId(successBody.id);
      setValues(initialValues);
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  if (accountId) {
    return (
      <div role="status">
        <p>Account created successfully! Your account id is {accountId}.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={values.name}
          onChange={(e) => handleChange("name", e.target.value)}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <span id="name-error">{errors.name}</span>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={values.email}
          onChange={(e) => handleChange("email", e.target.value)}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <span id="email-error">{errors.email}</span>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={values.password}
          onChange={(e) => handleChange("password", e.target.value)}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <span id="password-error">{errors.password}</span>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm Password</label>
        <input
          id="confirmPassword"
          type="password"
          value={values.confirmPassword}
          onChange={(e) => handleChange("confirmPassword", e.target.value)}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && (
          <span id="confirmPassword-error">{errors.confirmPassword}</span>
        )}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={values.acceptTerms}
            onChange={(e) => handleChange("acceptTerms", e.target.checked)}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <span id="acceptTerms-error">{errors.acceptTerms}</span>}
      </div>

      {submitError && <div role="alert">{submitError}</div>}

      <button type="submit" disabled={submitting}>
        {submitting ? "Submitting..." : "Sign Up"}
      </button>
    </form>
  );
}

import { useEffect, useRef, useState } from "react";

interface Metric {
