function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    typeof candidate.unit === "string"
  );
}

function isMetricArray(value: unknown): value is Metric[] {
  return Array.isArray(value) && value.every(isMetric);
}

function formatSecondsAgo(lastUpdated: Date | null, now: Date): string {
  if (lastUpdated === null) {
    return "never";
  }
  const seconds = Math.max(0, Math.round((now.getTime() - lastUpdated.getTime()) / 1000));
  if (seconds === 0) {
    return "just now";
  }
  return `${seconds} second${seconds === 1 ? "" : "s"} ago`;
}

export default function MetricsPanel(): React.JSX.Element {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<ReadonlySet<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState<Date>(() => new Date());

  const previousValuesRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    let cancelled = false;
    let isPolling = false;
    let pollTimeoutId: ReturnType<typeof setTimeout> | null = null;

    async function fetchMetrics(): Promise<void> {
      try {
        const response = await fetch("/api/metrics");
        if (!response.ok) {
          throw new Error(`Request failed with status ${response.status}`);
        }
        const responseBody: unknown = await response.json();
        if (cancelled) {
          return;
        }
        if (!isMetricArray(responseBody)) {
          throw new Error("Received malformed metrics data");
        }
        const fetchedMetrics = responseBody;

        const previousValues = previousValuesRef.current;
        const changed = new Set<string>();
        for (const metric of fetchedMetrics) {
          const previousValue = previousValues.get(metric.name);
          if (previousValue !== undefined && previousValue !== metric.value) {
            changed.add(metric.name);
          }
        }
        previousValuesRef.current = new Map(
          fetchedMetrics.map((metric) => [metric.name, metric.value]),
        );

        setMetrics(fetchedMetrics);
        setChangedNames(changed);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Failed to load metrics");
        }
      }
    }

    async function pollOnce(): Promise<void> {
      await fetchMetrics();
      if (isPolling && !cancelled) {
        pollTimeoutId = setTimeout(() => {
          void pollOnce();
        }, POLL_INTERVAL_MS);
      }
    }

    function startPolling(): void {
      if (isPolling) {
        return;
      }
      isPolling = true;
      void pollOnce();
    }

    function stopPolling(): void {
      isPolling = false;
      if (pollTimeoutId !== null) {
        clearTimeout(pollTimeoutId);
        pollTimeoutId = null;
      }
    }

    function handleVisibilityChange(): void {
      if (document.hidden) {
        stopPolling();
      } else {
        startPolling();
      }
    }

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      stopPolling();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    const tickId = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(tickId);
  }, []);

  return (
    <div style={styles.panel}>
      <div style={styles.header}>
        <h2 style={styles.title}>Metrics</h2>
        <span style={styles.updated}>Last updated {formatSecondsAgo(lastUpdated, now)}</span>
      </div>

      {error !== null && <div style={styles.error}>{error}</div>}

      {metrics.length === 0 && error === null ? (
        <div>Loading metrics…</div>
      ) : (
        <table style={styles.table}>
          <tbody>
            {metrics.map((metric) => {
              const rowStyle = changedNames.has(metric.name)
                ? { ...styles.row, ...styles.rowChanged }
                : styles.row;
              return (
                <tr key={metric.name} style={rowStyle}>
                  <td style={styles.cell}>{metric.name}</td>
                  <td style={styles.valueCell}>
                    {metric.value} {metric.unit}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}

