import { useEffect, useMemo, useState } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (item): item is Todo =>
        item &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean"
    );
  } catch {
    return [];
  }
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(loadTodos);
  const [filter, setFilter] = useState<Filter>("all");
  const [draft, setDraft] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos]
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function addTodo() {
    const text = draft.trim();
    if (!text) return;
    const newTodo: Todo = {
      id: crypto.randomUUID(),
      text,
      done: false,
    };
    setTodos((prev) => [...prev, newTodo]);
    setDraft("");
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo
      )
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEdit(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function commitEdit() {
    const text = editingText.trim();
    if (editingId === null) return;
    if (text) {
      setTodos((prev) =>
        prev.map((todo) =>
          todo.id === editingId ? { ...todo, text } : todo
        )
      );
    }
    setEditingId(null);
    setEditingText("");
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function moveUp(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index <= 0) return prev;
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  }

  function moveDown(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index === -1 || index >= prev.length - 1) return prev;
      const next = [...prev];
      [next[index + 1], next[index]] = [next[index], next[index + 1]];
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          addTodo();
        }}
      >
        <input
          type="text"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          placeholder="Add a new todo..."
          aria-label="New todo text"
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-board__filters">
        {(["all", "active", "done"] as Filter[]).map((f) => (
          <button
            key={f}
            type="button"
            aria-pressed={filter === f}
            disabled={filter === f}
            onClick={() => setFilter(f)}
          >
            {f[0].toUpperCase() + f.slice(1)}
          </button>
        ))}
      </div>

      <ul className="todo-board__list">
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((t) => t.id === todo.id);
          const isFirst = index === 0;
          const isLast = index === todos.length - 1;
          const isEditing = editingId === todo.id;

          return (
            <li key={todo.id} className="todo-board__item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
                aria-label={`Mark "${todo.text}" as ${
                  todo.done ? "active" : "done"
                }`}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(e) => setEditingText(e.target.value)}
                  onBlur={commitEdit}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") commitEdit();
                    if (e.key === "Escape") cancelEdit();
                  }}
                  aria-label="Edit todo text"
                />
              ) : (
                <span
                  className={todo.done ? "todo-board__text--done" : ""}
                  onDoubleClick={() => startEdit(todo)}
                >
                  {todo.text}
                </span>
              )}

              <button
                type="button"
                onClick={() => moveUp(todo.id)}
                disabled={isFirst}
                aria-label={`Move "${todo.text}" up`}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveDown(todo.id)}
                disabled={isLast}
                aria-label={`Move "${todo.text}" down`}
              >
                ↓
              </button>
              <button
                type="button"
                onClick={() => startEdit(todo)}
                aria-label={`Edit "${todo.text}"`}
              >
                Edit
              </button>
              <button
                type="button"
                onClick={() => deleteTodo(todo.id)}
                aria-label={`Delete "${todo.text}"`}
              >
                Delete
              </button>
            </li>
          );
        })}
      </ul>

      <p className="todo-board__count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { ChangeEvent, FormEvent, KeyboardEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board-items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (item): item is Todo =>
        typeof item === "object" &&
        item !== null &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean",
    );
  } catch {
    return [];
  }
}

function createId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(loadTodos);
  const [filter, setFilter] = useState<Filter>("all");
  const [newText, setNewText] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos]);

  function addTodo(e: FormEvent) {
    e.preventDefault();
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [...prev, { id: createId(), text, done: false }]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, done: !todo.done } : todo)),
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function commitEdit() {
    const text = editingText.trim();
    if (editingId === null) return;
    if (!text) {
      deleteTodo(editingId);
    } else {
      setTodos((prev) =>
        prev.map((todo) => (todo.id === editingId ? { ...todo, text } : todo)),
      );
    }
    setEditingId(null);
    setEditingText("");
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function handleEditKeyDown(e: KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Enter") {
      commitEdit();
    } else if (e.key === "Escape") {
      cancelEdit();
    }
  }

  function moveUp(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index <= 0) return prev;
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  }

  function moveDown(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index === -1 || index >= prev.length - 1) return prev;
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
  }

  const visibleTodos = todos.filter((todo) => {
    if (filter === "active") return !todo.done;
    if (filter === "done") return todo.done;
    return true;
  });

  const remainingCount = todos.filter((todo) => !todo.done).length;

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form onSubmit={addTodo}>
        <input
          type="text"
          value={newText}
          placeholder="Add a new task"
          onChange={(e: ChangeEvent<HTMLInputElement>) => setNewText(e.target.value)}
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-filters">
        {(["all", "active", "done"] as Filter[]).map((f) => (
          <button
            key={f}
            type="button"
            aria-pressed={filter === f}
            onClick={() => setFilter(f)}
          >
            {f[0].toUpperCase() + f.slice(1)}
          </button>
        ))}
      </div>

      <ul className="todo-list">
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((t) => t.id === todo.id);
          const isEditing = editingId === todo.id;
          return (
            <li key={todo.id}>
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
              />
              {isEditing ? (
                <input
                  type="text"
                  autoFocus
                  value={editingText}
                  onChange={(e: ChangeEvent<HTMLInputElement>) => setEditingText(e.target.value)}
                  onBlur={commitEdit}
                  onKeyDown={handleEditKeyDown}
                />
              ) : (
                <span
                  className={todo.done ? "done" : undefined}
                  onDoubleClick={() => startEditing(todo)}
                >
                  {todo.text}
                </span>
              )}
              <button type="button" onClick={() => startEditing(todo)} disabled={isEditing}>
                Edit
              </button>
              <button
                type="button"
                onClick={() => moveUp(todo.id)}
                disabled={index <= 0}
              >
                Move up
              </button>
              <button
                type="button"
                onClick={() => moveDown(todo.id)}
                disabled={index >= todos.length - 1}
              >
                Move down
              </button>
              <button type="button" onClick={() => deleteTodo(todo.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>

      <p>{remainingCount} item(s) remaining</p>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import type { ChangeEvent, FormEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed;
  } catch {
    return [];
  }
}

function createId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(() => loadTodos());
  const [newText, setNewText] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos],
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function handleAdd(event: FormEvent) {
    event.preventDefault();
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [...prev, { id: createId(), text, done: false }]);
    setNewText("");
  }

  function handleToggle(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo,
      ),
    );
  }

  function handleDelete(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEdit(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEdit(id: string) {
    const text = editingText.trim();
    if (!text) {
      handleDelete(id);
      return;
    }
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, text } : todo)),
    );
    setEditingId(null);
    setEditingText("");
  }

  function moveUp(index: number) {
    if (index === 0) return;
    setTodos((prev) => {
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  }

  function moveDown(index: number) {
    setTodos((prev) => {
      if (index === prev.length - 1) return prev;
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form onSubmit={handleAdd} className="todo-add-form">
        <input
          type="text"
          value={newText}
          placeholder="Add a new todo…"
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setNewText(event.target.value)
          }
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-filters">
        {(["all", "active", "done"] as Filter[]).map((option) => (
          <button
            key={option}
            type="button"
            aria-pressed={filter === option}
            onClick={() => setFilter(option)}
          >
            {option[0].toUpperCase() + option.slice(1)}
          </button>
        ))}
      </div>

      <p className="todo-count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>

      <ul className="todo-list">
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((item) => item.id === todo.id);
          const isEditing = editingId === todo.id;
          return (
            <li key={todo.id} className="todo-item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => handleToggle(todo.id)}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(event: ChangeEvent<HTMLInputElement>) =>
                    setEditingText(event.target.value)
                  }
                  onBlur={() => commitEdit(todo.id)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      event.preventDefault();
                      commitEdit(todo.id);
                    } else if (event.key === "Escape") {
                      cancelEdit();
                    }
                  }}
                />
              ) : (
                <span
                  className={todo.done ? "todo-text done" : "todo-text"}
                  onDoubleClick={() => startEdit(todo)}
                >
                  {todo.text}
                </span>
              )}

              <div className="todo-actions">
                <button
                  type="button"
                  onClick={() => moveUp(index)}
                  disabled={index === 0}
                  aria-label="Move up"
                >
                  ↑
                </button>
                <button
                  type="button"
                  onClick={() => moveDown(index)}
                  disabled={index === todos.length - 1}
                  aria-label="Move down"
                >
                  ↓
                </button>
                {isEditing ? (
                  <button type="button" onClick={() => commitEdit(todo.id)}>
                    Save
                  </button>
                ) : (
                  <button type="button" onClick={() => startEdit(todo)}>
                    Edit
                  </button>
                )}
                <button type="button" onClick={() => handleDelete(todo.id)}>
                  Delete
                </button>
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

interface ChatRoomProps {
  roomId: string;
}

const RECONNECT_DELAY_MS = 2000;

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.author === "string" &&
    typeof candidate.text === "string" &&
    typeof candidate.sentAt === "string"
  );
}

export default function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);
  const isUnmountedRef = useRef(false);

  useEffect(() => {
    isUnmountedRef.current = false;
    setMessages([]);
    setIsReconnecting(false);

    let isFirstConnectAttempt = true;

    const connect = () => {
      if (isUnmountedRef.current) return;

      const socket = new WebSocket(`wss://chat.example.com/rooms/${roomId}`);
      socketRef.current = socket;

      socket.addEventListener("open", () => {
        if (isUnmountedRef.current) return;
        isFirstConnectAttempt = false;
        setIsReconnecting(false);
      });

      socket.addEventListener("message", (event) => {
        if (isUnmountedRef.current) return;
        try {
          const parsed: unknown = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed]);
          } else {
            console.warn("Received malformed chat message", parsed);
          }
        } catch (error) {
          console.warn("Failed to parse chat message", error);
        }
      });

      const scheduleReconnect = () => {
        if (isUnmountedRef.current) return;
        if (!isFirstConnectAttempt) {
          setIsReconnecting(true);
        }
        isFirstConnectAttempt = false;
        reconnectTimerRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      };

      socket.addEventListener("close", scheduleReconnect);
      socket.addEventListener("error", () => {
        socket.close();
      });
    };

    connect();

    return () => {
      isUnmountedRef.current = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      const socket = socketRef.current;
      socketRef.current = null;
      if (socket) {
        socket.onclose = null;
        socket.onerror = null;
        socket.close();
      }
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(
      JSON.stringify({
        id: crypto.randomUUID(),
        author: "me",
        text,
        sentAt: new Date().toISOString(),
      }),
    );
    setDraft("");
  }, [draft]);

  const handleSubmit = useCallback(
    (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      sendMessage();
    },
    [sendMessage],
  );

  return (
    <div className="chat-room">
      {isReconnecting && (
        <div className="chat-room__banner" role="status">
          Reconnecting…
        </div>
      )}

      <ul className="chat-room__messages">
        {messages.map((message) => (
          <li key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__timestamp">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </li>
        ))}
        <div ref={messagesEndRef} />
      </ul>

      <form className="chat-room__composer" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  isLoading: boolean;
  error: string | null;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [isLoading, setIsLoading] = useState(ids.length > 0);
  const [error, setError] = useState<string | null>(null);

  const key = ids.join(",");

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setIsLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setIsLoading(true);
    setError(null);

    Promise.all(
      ids.map(async (id) => {
        const response = await fetch(`/api/users/${id}`);
        if (!response.ok) {
          throw new Error(`Failed to load user ${id}: ${response.status}`);
        }
        return (await response.json()) as User;
      }),
    )
      .then((users) => {
        if (cancelled) return;
        const byId: Record<string, User> = {};
        for (const user of users) {
          byId[user.id] = user;
        }
        setProfiles(byId);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to load user profiles");
      })
      .finally(() => {
        if (cancelled) return;
        setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  return { profiles, isLoading, error };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  const handleReset = () => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  };

  const handleSave = async () => {
    if (!hasChanges || isSaving) return;
    setIsSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="profile-editor">
      <img src={user.avatarUrl} alt={`${user.displayName}'s avatar`} className="profile-editor__avatar" />

      <label className="profile-editor__field">
        <span>Display name</span>
        <input
          type="text"
          value={displayName}
          onChange={(e) => setDisplayName(e.target.value)}
          disabled={isSaving}
        />
      </label>

      <label className="profile-editor__field">
        <span>Bio</span>
        <textarea value={bio} onChange={(e) => setBio(e.target.value)} disabled={isSaving} />
      </label>

      <div className="profile-editor__status">
        {hasChanges ? "Unsaved changes" : "No changes"}
      </div>

      {error && <div className="profile-editor__error">{error}</div>}

      <div className="profile-editor__actions">
        <button type="button" onClick={handleReset} disabled={!hasChanges || isSaving}>
          Reset
        </button>
        <button type="button" onClick={handleSave} disabled={!hasChanges || isSaving}>
          {isSaving ? "Saving..." : "Save"}
        </button>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UserProfileState {
  data: User | null;
  loading: boolean;
  error: string | null;
}

export interface UseUserProfilesResult {
  profiles: Record<string, UserProfileState>;
  loading: boolean;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

async function fetchUser(id: string, signal: AbortSignal): Promise<User> {
  const response = await fetch(`/api/users/${encodeURIComponent(id)}`, { signal });
  if (!response.ok) {
    throw new Error(`Failed to load user ${id}: ${response.status}`);
  }
  const body: unknown = await response.json();
  if (!isUser(body)) {
    throw new Error(`Malformed user response for ${id}`);
  }
  return body;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, UserProfileState>>({});

  const key = ids.join(",");

  useEffect(() => {
    const controller = new AbortController();

    setProfiles(
      Object.fromEntries(
        ids.map((id) => [id, { data: null, loading: true, error: null } as UserProfileState])
      )
    );

    ids.forEach((id) => {
      fetchUser(id, controller.signal)
        .then((data) => {
          setProfiles((prev) => ({ ...prev, [id]: { data, loading: false, error: null } }));
        })
        .catch((err) => {
          if (controller.signal.aborted) return;
          const message = err instanceof Error ? err.message : "Failed to load user";
          setProfiles((prev) => ({ ...prev, [id]: { data: null, loading: false, error: message } }));
        });
    });

    return () => controller.abort();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  const loading = ids.some((id) => profiles[id]?.loading ?? true);

  return { profiles, loading };
}

