        </button>
        <button type="button" onClick={handleSave} disabled={!hasChanges || saving}>
          {saving ? "Saving..." : "Save"}
        </button>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  errors: Record<string, string>;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

async function fetchUser(id: string): Promise<User> {
  const response = await fetch(`/api/users/${encodeURIComponent(id)}`);
  if (!response.ok) {
    throw new Error(`Failed to load user ${id}: ${response.status}`);
  }
  const data: unknown = await response.json();
  if (!isUser(data)) {
    throw new Error(`Malformed user data for ${id}`);
  }
  return data;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(ids.length > 0);

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setErrors({});
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);

    Promise.allSettled(ids.map((id) => fetchUser(id))).then((results) => {
      if (cancelled) return;

      const nextProfiles: Record<string, User> = {};
      const nextErrors: Record<string, string> = {};

      results.forEach((result, index) => {
        const id = ids[index];
        if (result.status === "fulfilled") {
          nextProfiles[id] = result.value;
        } else {
          nextErrors[id] =
            result.reason instanceof Error ? result.reason.message : "Failed to load user";
        }
      });

      setProfiles(nextProfiles);
      setErrors(nextErrors);
      setLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [ids.join(",")]);

  return { profiles, loading, errors };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  const handleReset = () => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  };

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setSaving(false);
    }
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        void handleSave();
      }}
    >
      <div>
        <img src={user.avatarUrl} alt={`${displayName}'s avatar`} width={64} height={64} />
      </div>

      <label htmlFor="displayName">Display name</label>
      <input
        id="displayName"
        type="text"
        value={displayName}
        onChange={(e) => setDisplayName(e.target.value)}
        disabled={saving}
      />

      <label htmlFor="bio">Bio</label>
      <textarea
        id="bio"
        value={bio}
        onChange={(e) => setBio(e.target.value)}
        disabled={saving}
      />

      <p>{hasChanges ? "Unsaved changes" : "No unsaved changes"}</p>
      {error && <p role="alert">{error}</p>}

      <button type="submit" disabled={saving || !hasChanges}>
        {saving ? "Saving..." : "Save"}
      </button>
      <button type="button" onClick={handleReset} disabled={saving || !hasChanges}>
        Reset
      </button>
    </form>
  );
}

import { useEffect, useMemo, useState } from "react";
import type { ChangeEvent, FormEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (item): item is Todo =>
        item &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean"
    );
  } catch {
    return [];
  }
}

function createId(): string {
  return typeof crypto !== "undefined" && "randomUUID" in crypto
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(() => loadTodos());
  const [draft, setDraft] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos]
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function handleAdd(event: FormEvent) {
    event.preventDefault();
    const text = draft.trim();
    if (!text) return;
    setTodos((prev) => [...prev, { id: createId(), text, done: false }]);
    setDraft("");
  }

  function handleDraftChange(event: ChangeEvent<HTMLInputElement>) {
    setDraft(event.target.value);
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo
      )
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEdit(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEdit(id: string) {
    const text = editingText.trim();
    if (!text) {
      deleteTodo(id);
      return;
    }
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, text } : todo))
    );
    setEditingId(null);
    setEditingText("");
  }

  function moveTodo(id: string, direction: -1 | 1) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      const targetIndex = index + direction;
      if (index === -1 || targetIndex < 0 || targetIndex >= prev.length) {
        return prev;
      }
      const next = [...prev];
      [next[index], next[targetIndex]] = [next[targetIndex], next[index]];
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form onSubmit={handleAdd} className="todo-board__add-form">
        <input
          type="text"
          value={draft}
          onChange={handleDraftChange}
          placeholder="What needs doing?"
          aria-label="New todo text"
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-board__filters" role="group" aria-label="Filter todos">
        {(["all", "active", "done"] as const).map((option) => (
          <button
            key={option}
            type="button"
            onClick={() => setFilter(option)}
            aria-pressed={filter === option}
          >
            {option[0].toUpperCase() + option.slice(1)}
          </button>
        ))}
      </div>

      <p className="todo-board__count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>

      <ul className="todo-board__list">
        {visibleTodos.map((todo) => {
          const originalIndex = todos.findIndex((item) => item.id === todo.id);
          const isEditing = editingId === todo.id;

          return (
            <li key={todo.id} className="todo-board__item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
                aria-label={`Mark "${todo.text}" as ${
                  todo.done ? "active" : "done"
                }`}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(event) => setEditingText(event.target.value)}
                  onBlur={() => commitEdit(todo.id)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      event.preventDefault();
                      commitEdit(todo.id);
                    } else if (event.key === "Escape") {
                      event.preventDefault();
                      cancelEdit();
                    }
                  }}
                />
              ) : (
                <span
                  className={todo.done ? "todo-board__text--done" : undefined}
                  onDoubleClick={() => startEdit(todo)}
                >
                  {todo.text}
                </span>
              )}

              <button
                type="button"
                onClick={() => moveTodo(todo.id, -1)}
                disabled={originalIndex <= 0}
                aria-label={`Move "${todo.text}" up`}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveTodo(todo.id, 1)}
                disabled={originalIndex === todos.length - 1}
                aria-label={`Move "${todo.text}" down`}
              >
                ↓
              </button>
              <button type="button" onClick={() => startEdit(todo)}>
                Edit
              </button>
              <button type="button" onClick={() => deleteTodo(todo.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import Foundation
import SwiftUI

struct SearchResult: Identifiable, Decodable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = "" {
        didSet { scheduleSearch() }
    }
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private var searchTask: Task<Void, Never>?
    private let debounceInterval: Duration = .milliseconds(300)
    private let session: URLSession

    init(session: URLSession = .shared) {
        self.session = session
    }

    private func scheduleSearch() {
        searchTask?.cancel()

        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            results = []
            errorMessage = nil
            isLoading = false
            return
        }

        searchTask = Task {
            try? await Task.sleep(for: debounceInterval)
            guard !Task.isCancelled else { return }
            await performSearch(for: trimmed)
        }
    }

    private func performSearch(for text: String) async {
        isLoading = true
        errorMessage = nil

        var components = URLComponents(string: "https://api.example.com/search")
        components?.queryItems = [URLQueryItem(name: "q", value: text)]

        guard let url = components?.url else {
            isLoading = false
            errorMessage = "Invalid search URL."
            return
        }

        do {
            let (data, response) = try await session.data(from: url)
            guard !Task.isCancelled else { return }

            if let httpResponse = response as? HTTPURLResponse, !(200..<300).contains(httpResponse.statusCode) {
                throw URLError(.badServerResponse)
            }

            let decoded = try JSONDecoder().decode([SearchResult].self, from: data)
            results = decoded
            isLoading = false
        } catch {
            guard !Task.isCancelled else { return }
            results = []
            isLoading = false
            errorMessage = error.localizedDescription
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 0) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .padding()

            content
        }
        .frame(minWidth: 320, minHeight: 400)
    }

    @ViewBuilder
    private var content: some View {
        if viewModel.isLoading {
            ProgressView()
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if let errorMessage = viewModel.errorMessage {
            Text(errorMessage)
                .foregroundStyle(.red)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            Text("Start typing to search.")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if viewModel.results.isEmpty {
            Text("No results.")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            List(viewModel.results) { result in
                VStack(alignment: .leading) {
                    Text(result.title)
                    Text(result.subtitle)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }
        }
    }
}

import Foundation
import SwiftUI

struct SearchResult: Identifiable, Decodable {
    let id: String
    let title: String
    let subtitle: String
}

private struct SearchResponse: Decodable {
    let results: [SearchResult]
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = "" {
        didSet { scheduleSearch() }
    }
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private let session: URLSession
    private let debounceInterval: Duration
    private var searchTask: Task<Void, Never>?

    init(session: URLSession = .shared, debounceInterval: Duration = .milliseconds(300)) {
        self.session = session
        self.debounceInterval = debounceInterval
    }

    private func scheduleSearch() {
        searchTask?.cancel()
        let currentQuery = query
        searchTask = Task {
            try? await Task.sleep(for: debounceInterval)
            guard !Task.isCancelled else { return }
            await performSearch(for: currentQuery)
        }
    }

    private func performSearch(for text: String) async {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            results = []
            errorMessage = nil
            isLoading = false
            return
        }

        guard var components = URLComponents(string: "https://api.example.com/search") else {
            errorMessage = "Invalid search URL."
            return
        }
        components.queryItems = [URLQueryItem(name: "q", value: trimmed)]
        guard let url = components.url else {
            errorMessage = "Invalid search URL."
            return
        }

        isLoading = true
        errorMessage = nil

        do {
            let (data, response) = try await session.data(from: url)
            guard !Task.isCancelled else { return }

            if let httpResponse = response as? HTTPURLResponse,
               !(200..<300).contains(httpResponse.statusCode) {
                throw URLError(.badServerResponse)
            }

            let decoded = try JSONDecoder().decode(SearchResponse.self, from: data)
            guard !Task.isCancelled else { return }

            results = decoded.results
            isLoading = false
        } catch is CancellationError {
            // Superseded by a newer query; leave state to the task that follows.
        } catch {
            guard !Task.isCancelled else { return }
            results = []
            errorMessage = "Search failed: \(error.localizedDescription)"
            isLoading = false
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        NavigationStack {
            VStack(spacing: 0) {
                TextField("Search", text: $viewModel.query)
