    }

    private func placeholder(systemImage: String, message: String) -> some View {
        VStack(spacing: 8) {
            Image(systemName: systemImage)
                .font(.largeTitle)
            Text(message)
        }
        .foregroundStyle(.secondary)
    }
}

import SwiftUI
import Combine

final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [TimeInterval] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startDate: Date?
    private var accumulated: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startDate = Date()
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            self?.tick()
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        accumulated = elapsed
    }

    func reset() {
        stop()
        elapsed = 0
        accumulated = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        laps.append(elapsed)
    }

    private func tick() {
        guard let startDate else { return }
        elapsed = accumulated + Date().timeIntervalSince(startDate)
    }
}

enum TimeFormatter {
    static func format(_ interval: TimeInterval) -> String {
        let totalHundredths = Int((interval * 100).rounded())
        let minutes = (totalHundredths / 6000)
        let seconds = (totalHundredths / 100) % 60
        let hundredths = totalHundredths % 100
        return String(format: "%02d:%02d.%02d", minutes, seconds, hundredths)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(TimeFormatter.format(viewModel.elapsed))
                .font(.system(size: 56, weight: .medium, design: .monospaced))

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    viewModel.isRunning ? viewModel.stop() : viewModel.start()
                }
                Button("Lap") {
                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)
                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(viewModel.isRunning)
            }
            .buttonStyle(.bordered)

            List {
                ForEach(Array(viewModel.laps.enumerated().reversed()), id: \.offset) { index, lap in
                    HStack {
                        Text("Lap \(index + 1)")
                        Spacer()
                        Text(TimeFormatter.format(splitTime(at: index)))
                            .font(.system(.body, design: .monospaced))
                    }
                }
            }
        }
        .padding()
    }

    private func splitTime(at index: Int) -> TimeInterval {
        index == 0 ? viewModel.laps[0] : viewModel.laps[index] - viewModel.laps[index - 1]
    }
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  errors: Record<string, string>;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(ids.length > 0);

  const key = ids.join(",");

  useEffect(() => {
    const idList = key.length > 0 ? key.split(",") : [];

    if (idList.length === 0) {
      setProfiles({});
      setErrors({});
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);

    type FetchResult = { id: string; user: User } | { id: string; error: string };

    Promise.all(
      idList.map(async (id): Promise<FetchResult> => {
        try {
          const res = await fetch(`/api/users/${id}`);
          if (!res.ok) {
            throw new Error(`Request for user ${id} failed with status ${res.status}`);
          }
          const data: unknown = await res.json();
          if (!isUser(data)) {
            throw new Error(`Response for user ${id} was not a valid user`);
          }
          return { id, user: data };
        } catch (err) {
          return { id, error: err instanceof Error ? err.message : "Failed to load user" };
        }
      })
    ).then((results) => {
      if (cancelled) return;

      const nextProfiles: Record<string, User> = {};
      const nextErrors: Record<string, string> = {};
      for (const result of results) {
        if ("user" in result) {
          nextProfiles[result.id] = result.user;
        } else {
          nextErrors[result.id] = result.error;
        }
      }

      setProfiles(nextProfiles);
      setErrors(nextErrors);
      setLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [key]);

  return { profiles, loading, errors };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  const handleReset = () => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  };

  const handleSave = async () => {
    if (!hasChanges || saving) return;
    setSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="profile-editor">
      <img src={user.avatarUrl} alt={`${displayName}'s avatar`} className="profile-editor__avatar" />

      <label className="profile-editor__field">
        <span>Display name</span>
        <input
          type="text"
          value={displayName}
          onChange={(e) => setDisplayName(e.target.value)}
          disabled={saving}
        />
      </label>

      <label className="profile-editor__field">
        <span>Bio</span>
        <textarea
          value={bio}
          onChange={(e) => setBio(e.target.value)}
          disabled={saving}
        />
      </label>

      <p className="profile-editor__status">
        {hasChanges ? "You have unsaved changes." : "No unsaved changes."}
      </p>

      {error && <p className="profile-editor__error">{error}</p>}

      <div className="profile-editor__actions">
        <button type="button" onClick={handleReset} disabled={!hasChanges || saving}>
          Reset
        </button>
        <button type="button" onClick={handleSave} disabled={!hasChanges || saving}>
          {saving ? "Saving..." : "Save"}
        </button>
      </div>
    </div>
  );
}

