/// Shared in-memory cache of downloaded thumbnails, keyed by URL, so scrolling
/// back through a grid doesn't re-download images that are already on screen once.
@MainActor
public final class ThumbnailImageCache {
    public static let shared = ThumbnailImageCache()

    private let cache = NSCache<NSURL, PlatformImage>()

    private init() {}

    public func image(for url: URL) -> PlatformImage? {
        cache.object(forKey: url as NSURL)
    }

    public func insert(_ image: PlatformImage, for url: URL) {
        cache.setObject(image, forKey: url as NSURL)
    }
}

