            }

            Section("Refresh") {
                Stepper(value: $store.refreshInterval, in: 15...3600, step: 15) {
                    Text("Refresh Interval: \(Int(store.refreshInterval))s")
                }
            }
        }
        .padding()
        .navigationTitle("Settings")
    }
}

