/// Stores user preferences in `UserDefaults` and stays in sync if they're
/// changed elsewhere (e.g. another window, or directly via `defaults write`).
@MainActor
final class SettingsStore: ObservableObject {
    enum Theme: String, CaseIterable, Identifiable {
        case system
        case light
        case dark

        var id: String { rawValue }

        var displayName: String {
            switch self {
            case .system: return "System"
            case .light: return "Light"
            case .dark: return "Dark"
            }
        }
    }

    private enum Key {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    private static let defaultRefreshInterval: TimeInterval = 60

    @Published var displayName: String {
        didSet {
            guard !isApplyingExternalChange, displayName != oldValue else { return }
            defaults.set(displayName, forKey: Key.displayName)
        }
    }

    @Published var theme: Theme {
        didSet {
            guard !isApplyingExternalChange, theme != oldValue else { return }
            defaults.set(theme.rawValue, forKey: Key.theme)
        }
    }

    @Published var notificationsEnabled: Bool {
        didSet {
            guard !isApplyingExternalChange, notificationsEnabled != oldValue else { return }
            defaults.set(notificationsEnabled, forKey: Key.notificationsEnabled)
        }
    }

    @Published var refreshInterval: TimeInterval {
        didSet {
            guard !isApplyingExternalChange, refreshInterval != oldValue else { return }
            defaults.set(refreshInterval, forKey: Key.refreshInterval)
        }
    }

    private let defaults: UserDefaults
    private var observer: NSObjectProtocol?

    /// Guards against re-persisting values we just loaded *from* `defaults`,
    /// which would otherwise re-trigger `didChangeNotification` in a loop.
    private var isApplyingExternalChange = false

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.displayName = defaults.string(forKey: Key.displayName) ?? ""
        self.theme = Theme(rawValue: defaults.string(forKey: Key.theme) ?? "") ?? .system
        self.notificationsEnabled = defaults.object(forKey: Key.notificationsEnabled) as? Bool ?? true
        self.refreshInterval = defaults.object(forKey: Key.refreshInterval) as? TimeInterval ?? Self.defaultRefreshInterval

        observer = NotificationCenter.default.addObserver(
            forName: UserDefaults.didChangeNotification,
            object: defaults,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor in
                self?.reloadFromDefaults()
            }
        }
    }

    deinit {
        if let observer {
            NotificationCenter.default.removeObserver(observer)
        }
    }

    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Key.displayName) ?? ""
        if newDisplayName != displayName {
            displayName = newDisplayName
        }

        let newTheme = Theme(rawValue: defaults.string(forKey: Key.theme) ?? "") ?? .system
        if newTheme != theme {
            theme = newTheme
        }

        let newNotificationsEnabled = defaults.object(forKey: Key.notificationsEnabled) as? Bool ?? true
        if newNotificationsEnabled != notificationsEnabled {
            notificationsEnabled = newNotificationsEnabled
        }

        let newRefreshInterval = defaults.object(forKey: Key.refreshInterval) as? TimeInterval ?? Self.defaultRefreshInterval
        if newRefreshInterval != refreshInterval {
            refreshInterval = newRefreshInterval
        }
    }
}

struct SettingsScreen: View {
    @ObservedObject var store: SettingsStore

    private static let refreshIntervalOptions: [TimeInterval] = [15, 30, 60, 300, 900]

    var body: some View {
        Form {
            Section("Profile") {
                TextField("Display Name", text: $store.displayName)
            }

            Section("Appearance") {
                Picker("Theme", selection: $store.theme) {
                    ForEach(SettingsStore.Theme.allCases) { theme in
                        Text(theme.displayName).tag(theme)
                    }
                }
            }

            Section("Notifications") {
                Toggle("Enable Notifications", isOn: $store.notificationsEnabled)
            }

            Section("Sync") {
                Picker("Refresh Interval", selection: $store.refreshInterval) {
                    ForEach(Self.refreshIntervalOptions, id: \.self) { interval in
                        Text(Self.label(for: interval)).tag(interval)
                    }
                }
            }
        }
        .padding()
    }

    private static func label(for interval: TimeInterval) -> String {
        if interval < 60 {
            return "\(Int(interval))s"
        }
        return "\(Int(interval / 60))m"
    }
}

