/// A downloaded thumbnail plus the moment it was fetched, so cached
/// entries keep showing the original download date on re-display.
struct CachedThumbnail {
    let image: PlatformImage
    let downloadDate: Date
}

/// Shared in-memory cache so scrolling the grid doesn't re-download
/// thumbnails that are already on screen.
actor ThumbnailCache {
    static let shared = ThumbnailCache()

    private var storage: [URL: CachedThumbnail] = [:]

    func thumbnail(for url: URL) -> CachedThumbnail? {
        storage[url]
    }

    func store(_ thumbnail: CachedThumbnail, for url: URL) {
        storage[url] = thumbnail
    }
}

/// A SwiftUI grid that displays photo thumbnails downloaded from a list of URLs.
public struct ThumbnailGrid: View {
    public let imageURLs: [URL]

    private let columns = [GridItem(.adaptive(minimum: 100), spacing: 12)]

    public init(imageURLs: [URL]) {
        self.imageURLs = imageURLs
    }

    public var body: some View {
        ScrollView {
            LazyVGrid(columns: columns, spacing: 12) {
                ForEach(imageURLs, id: \.self) { url in
                    ThumbnailCell(url: url)
                }
            }
            .padding()
        }
    }
}

private struct ThumbnailCell: View {
    let url: URL

    @State private var thumbnail: CachedThumbnail?
    @State private var loadFailed = false

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color.secondary.opacity(0.2))

                if let thumbnail {
                    Image(platformImage: thumbnail.image)
                        .resizable()
                        .scaledToFill()
                } else if loadFailed {
                    Image(systemName: "photo")
                        .foregroundStyle(.secondary)
                } else {
                    ProgressView()
                }
            }
            .frame(width: 100, height: 100)
            .clipShape(RoundedRectangle(cornerRadius: 8))

            if let thumbnail {
                Text(thumbnail.downloadDate, format: .relative(presentation: .named))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            }
        }
        .task(id: url) {
            await load()
        }
    }

    private func load() async {
        loadFailed = false

        if let cached = await ThumbnailCache.shared.thumbnail(for: url) {
            thumbnail = cached
            return
        }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            guard let image = PlatformImage(data: data) else {
                loadFailed = true
                return
            }

            let cached = CachedThumbnail(image: image, downloadDate: Date())
            await ThumbnailCache.shared.store(cached, for: url)
            thumbnail = cached
        } catch {
            loadFailed = true
        }
    }
}

