import Foundation
import SwiftUI

struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []

    private let url = URL(string: "wss://chat.example.com/room")!
    private let session = URLSession(configuration: .default)
    private var task: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30

    func connect() {
        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()
        reconnectDelay = 1
        listen()
    }

    func disconnect() {
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }

    func send(text: String) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        let outgoing = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(outgoing) else { return }
        task?.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                self?.scheduleReconnect()
            }
        }
    }

    private func listen() {
        task?.receive { [weak self] result in
            Task { @MainActor in
                guard let self else { return }
                switch result {
                case .success(let message):
                    self.handle(message)
                    self.listen()
                case .failure:
                    self.scheduleReconnect()
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = Data(text.utf8)
        @unknown default:
            return
        }
        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
    }

    private func scheduleReconnect() {
        task?.cancel()
        task = nil
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            self?.connect()
        }
    }
}

