// MARK: - Cancellation-safe continuation helper
//
// Both legacy APIs have no cancel method, so a cancelled Task can only stop
// *waiting* for the callback, not stop the callback from eventually firing.
// This box lets whichever of {legacy callback, onCancel} runs first resume
// the continuation, and makes the other one a safe no-op.

private final class ResumeOnce<T> {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<T, Error>?

    func setContinuation(_ continuation: CheckedContinuation<T, Error>) {
        lock.lock()
        defer { lock.unlock() }
        self.continuation = continuation
    }

    func resume(with result: Result<T, Error>) {
        lock.lock()
        let continuation = self.continuation
        self.continuation = nil
        lock.unlock()
        continuation?.resume(with: result)
    }
}

// MARK: - Modern async/await wrappers

extension LegacyGeocoder {
    func geocode(_ address: String) async throws -> (Double, Double) {
        let box = ResumeOnce<(Double, Double)>()
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                box.setContinuation(continuation)
                geocode(address) { result in
                    box.resume(with: result)
                }
            }
        } onCancel: {
            box.resume(with: .failure(CancellationError()))
        }
    }
}

/// Wraps a single `LegacyUploader`, whose `onProgress`/`onFinish` slots can
/// only ever track one in-flight upload. Each instance supports exactly one
/// `upload(file:)` call; a second call throws rather than silently
/// overwriting the first upload's callbacks.
final class UploadProgressBridge {
    private let uploader = LegacyUploader()
    private let progressContinuation: AsyncStream<Double>.Continuation
    let progress: AsyncStream<Double>

    private let lock = NSLock()
    private var hasStarted = false

    init() {
        var progressContinuation: AsyncStream<Double>.Continuation!
        self.progress = AsyncStream { progressContinuation = $0 }
        self.progressContinuation = progressContinuation
    }

    enum UploadError: Error {
        case alreadyStarted
    }

    /// Synchronous so `NSLock` locking stays out of the async function body.
    private func markStarted() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        let alreadyStarted = hasStarted
        hasStarted = true
        return alreadyStarted
    }

    func upload(file: URL) async throws {
        guard !markStarted() else {
            throw UploadError.alreadyStarted
        }

        let box = ResumeOnce<Void>()
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                box.setContinuation(continuation)
                uploader.onProgress = { [progressContinuation] value in
                    progressContinuation.yield(value)
                }
                uploader.onFinish = { [progressContinuation] error in
                    progressContinuation.finish()
                    if let error {
                        box.resume(with: .failure(error))
                    } else {
                        box.resume(with: .success(()))
                    }
                }
                uploader.start(file: file)
            }
        } onCancel: {
            progressContinuation.finish()
            box.resume(with: .failure(CancellationError()))
        }
    }
}

