}

import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const REFRESH_INTERVAL_MS = 10_000;

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [secondsAgo, setSecondsAgo] = useState(0);
  const previousValuesRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    let cancelled = false;

    const fetchMetrics = async () => {
      try {
        const response = await fetch("/api/metrics");
        if (!response.ok) {
          throw new Error(`Request failed with status ${response.status}`);
        }
        const data: Metric[] = await response.json();
        if (cancelled) return;

        const previousValues = previousValuesRef.current;
        const nextChanged = new Set<string>();
        for (const metric of data) {
          const previous = previousValues.get(metric.name);
          if (previous !== undefined && previous !== metric.value) {
            nextChanged.add(metric.name);
          }
        }

        previousValuesRef.current = new Map(
          data.map((metric) => [metric.name, metric.value])
        );

        setMetrics(data);
        setChangedNames(nextChanged);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Failed to load metrics");
        }
      }
    };

    let intervalId: ReturnType<typeof setInterval> | null = null;

    const startPolling = () => {
      if (intervalId !== null) return;
      fetchMetrics();
      intervalId = setInterval(fetchMetrics, REFRESH_INTERVAL_MS);
    };

    const stopPolling = () => {
      if (intervalId !== null) {
        clearInterval(intervalId);
        intervalId = null;
      }
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        startPolling();
      }
    };

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      stopPolling();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    if (!lastUpdated) return;

    const tick = () => {
      setSecondsAgo(Math.max(0, Math.floor((Date.now() - lastUpdated.getTime()) / 1000)));
    };

    tick();
    const timerId = setInterval(tick, 1000);
    return () => clearInterval(timerId);
  }, [lastUpdated]);

  return (
    <div className="metrics-panel">
      <div className="metrics-panel-header">
        <h2>Metrics</h2>
        <span className="metrics-panel-updated">
          {lastUpdated ? `Last updated ${secondsAgo} second${secondsAgo === 1 ? "" : "s"} ago` : "Loading…"}
        </span>
      </div>
      {error && <div className="metrics-panel-error">{error}</div>}
      <ul className="metrics-panel-list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={changedNames.has(metric.name) ? "metrics-panel-item changed" : "metrics-panel-item"}
          >
            <span className="metrics-panel-name">{metric.name}</span>
            <span className="metrics-panel-value">
              {metric.value} {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.name === "string" &&
    typeof candidate.email === "string"
  );
}

function isUserArray(value: unknown): value is User[] {
  return Array.isArray(value) && value.every(isUser);
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  useEffect(() => {
    if (debouncedQuery.trim() === "") {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json() as Promise<unknown>;
      })
      .then((data) => {
        if (!isUserArray(data)) {
          throw new Error("Received malformed user data");
        }
        setUsers(data);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
        setUsers([]);
        setLoading(false);
      });

    return () => controller.abort();
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label>
          Sort by:{" "}
          <select
            value={sortField}
            onChange={(e) => setSortField(e.target.value as SortField)}
          >
            <option value="name">Name</option>
            <option value="email">Email</option>
          </select>
        </label>
      </div>

      {loading && <div>Loading...</div>}
      {error && <div role="alert">Error: {error}</div>}

      {!loading && !error && debouncedQuery.trim() !== "" && (
        <div>{sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}</div>
      )}

      <ul>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            {user.name} ({user.email})
          </li>
        ))}
      </ul>
    </div>
  );
}

import Foundation
import SwiftUI

struct ChatMessage: Identifiable, Codable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: ObservableObject {
    nonisolated static let defaultReconnectDelay: TimeInterval = 3
    private static let nanosecondsPerSecond: Double = 1_000_000_000

    private nonisolated static var defaultURL: URL {
        guard let url = URL(string: "wss://chat.example.com/room") else {
            preconditionFailure("Invalid default chat URL")
        }
        return url
    }

    @Published private(set) var messages: [ChatMessage] = []

    private let url: URL
    private let session: URLSession
    private var task: URLSessionWebSocketTask?
    private let reconnectDelay: TimeInterval
    private var reconnectTask: Task<Void, Never>?
    private var isStopped = false

    init(
        url: URL = ChatConnection.defaultURL,
        session: URLSession = .shared,
        reconnectDelay: TimeInterval = ChatConnection.defaultReconnectDelay
    ) {
        self.url = url
        self.session = session
        self.reconnectDelay = reconnectDelay
    }

    func connect() {
        isStopped = false
        reconnectTask?.cancel()
        reconnectTask = nil

        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()
        listen(on: task)
    }

    func stop() {
        isStopped = true
        reconnectTask?.cancel()
        reconnectTask = nil
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }

    func send(text: String) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task else { return }

        let message = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(message) else { return }
        let payload = String(decoding: data, as: UTF8.self)

        task.send(.string(payload)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                self?.scheduleReconnect()
            }
        }

        messages.append(message)
    }

    private func listen(on task: URLSessionWebSocketTask) {
        task.receive { [weak self] result in
            guard let self else { return }
            switch result {
            case .failure:
                Task { @MainActor in
                    self.scheduleReconnect()
                }
            case .success(let message):
                Task { @MainActor in
                    self.handle(message)
                    self.listen(on: task)
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = Data(text.utf8)
        @unknown default:
            return
        }

        guard let decoded = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(decoded)
    }

    private func scheduleReconnect() {
        guard !isStopped, reconnectTask == nil else { return }
        task = nil
        reconnectTask = Task { [weak self] in
            guard let self else { return }
            let nanoseconds = self.reconnectDelay * Self.nanosecondsPerSecond
            try? await Task.sleep(nanoseconds: UInt64(nanoseconds))
            guard !Task.isCancelled else { return }
            self.reconnectTask = nil
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var connection = ChatConnection()
    @State private var draft: String = ""

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(connection.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .padding(.horizontal)
                        }
                    }
                    .padding(.vertical, 8)
                }
                .onChange(of: connection.messages) { newMessages in
                    guard let lastId = newMessages.last?.id else { return }
                    withAnimation {
                        proxy.scrollTo(lastId, anchor: .bottom)
                    }
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit(sendDraft)
                Button("Send", action: sendDraft)
                    .disabled(draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { connection.connect() }
        .onDisappear { connection.stop() }
    }

    private func sendDraft() {
        connection.send(text: draft)
        draft = ""
    }
}

