  }

  function toggleDone(id: string) {
    setItems((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, done: !item.done } : item,
      ),
    );
  }

  function deleteItem(id: string) {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(item: TodoItem) {
    setEditingId(item.id);
    setEditingText(item.text);
  }

  function commitEdit() {
    if (editingId === null) return;
    const text = editingText.trim();
    setItems((prev) =>
      prev.map((item) =>
        item.id === editingId
          ? { ...item, text: text || item.text }
          : item,
      ),
    );
    setEditingId(null);
    setEditingText("");
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function moveItem(id: string, direction: -1 | 1) {
    setItems((prev) => {
      const index = prev.findIndex((item) => item.id === id);
      const targetIndex = index + direction;
      if (index === -1 || targetIndex < 0 || targetIndex >= prev.length) {
        return prev;
      }
      const next = [...prev];
      [next[index], next[targetIndex]] = [next[targetIndex], next[index]];
      return next;
    });
  }

  return (
    <div>
      <h1>Todo Board</h1>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          addItem();
        }}
      >
        <input
          type="text"
          value={newText}
          onChange={(e) => setNewText(e.target.value)}
          placeholder="Add a new item"
        />
        <button type="submit">Add</button>
      </form>

      <div role="group" aria-label="Filter items">
        {(["all", "active", "done"] as const).map((f) => (
          <button
            key={f}
            type="button"
            aria-pressed={filter === f}
            onClick={() => setFilter(f)}
            disabled={filter === f}
          >
            {f}
          </button>
        ))}
      </div>

      <p>{remainingCount} item(s) remaining</p>

      <ul>
        {visibleItems.map((item) => {
          const index = items.findIndex((i) => i.id === item.id);
          const isEditing = editingId === item.id;
          return (
            <li key={item.id}>
              <input
                type="checkbox"
                checked={item.done}
                onChange={() => toggleDone(item.id)}
                aria-label={`Mark "${item.text}" as ${item.done ? "active" : "done"}`}
              />

              {isEditing ? (
                <form
                  style={{ display: "inline" }}
                  onSubmit={(e) => {
                    e.preventDefault();
                    commitEdit();
                  }}
                >
                  <input
                    type="text"
                    value={editingText}
                    autoFocus
                    onChange={(e) => setEditingText(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Escape") cancelEdit();
                    }}
                    onBlur={commitEdit}
                  />
                </form>
              ) : (
                <span
                  onDoubleClick={() => startEditing(item)}
                  style={{ textDecoration: item.done ? "line-through" : "none" }}
                >
                  {item.text}
                </span>
              )}

              <button type="button" onClick={() => startEditing(item)}>
                Edit
              </button>
              <button
                type="button"
                onClick={() => moveItem(item.id, -1)}
                disabled={index <= 0}
              >
                Move up
              </button>
              <button
                type="button"
                onClick={() => moveItem(item.id, 1)}
                disabled={index === -1 || index >= items.length - 1}
              >
                Move down
              </button>
              <button type="button" onClick={() => deleteItem(item.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed;
  } catch {
    return [];
  }
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(loadTodos);
  const [filter, setFilter] = useState<Filter>("all");
  const [newText, setNewText] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos]
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function addTodo() {
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [
      ...prev,
      { id: crypto.randomUUID(), text, done: false },
    ]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo
      )
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
  }

  function startEditing(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function commitEdit() {
    const text = editingText.trim();
    if (editingId === null) return;
    if (!text) {
      deleteTodo(editingId);
    } else {
      setTodos((prev) =>
        prev.map((todo) =>
          todo.id === editingId ? { ...todo, text } : todo
        )
      );
    }
    setEditingId(null);
    setEditingText("");
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function moveUp(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index <= 0) return prev;
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  }

  function moveDown(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index === -1 || index >= prev.length - 1) return prev;
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form
        onSubmit={(event) => {
          event.preventDefault();
          addTodo();
        }}
      >
        <input
          type="text"
          value={newText}
          onChange={(event) => setNewText(event.target.value)}
          placeholder="Add a new task..."
          aria-label="New task"
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-board__filters">
        {(["all", "active", "done"] as const).map((value) => (
          <button
            key={value}
            type="button"
            onClick={() => setFilter(value)}
            aria-pressed={filter === value}
            disabled={filter === value}
          >
            {value[0].toUpperCase() + value.slice(1)}
          </button>
        ))}
      </div>

      <p>{remainingCount} item(s) remaining</p>

      <ul className="todo-board__list">
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((item) => item.id === todo.id);
          const isEditing = editingId === todo.id;
          return (
            <li key={todo.id} className="todo-board__item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
                aria-label={`Mark "${todo.text}" as done`}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(event) => setEditingText(event.target.value)}
                  onBlur={commitEdit}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") commitEdit();
                    if (event.key === "Escape") cancelEdit();
                  }}
                  aria-label="Edit task"
                />
              ) : (
                <span
                  onDoubleClick={() => startEditing(todo)}
                  style={{
                    textDecoration: todo.done ? "line-through" : "none",
                  }}
                >
                  {todo.text}
                </span>
              )}

              <button type="button" onClick={() => startEditing(todo)}>
                Edit
              </button>
              <button
                type="button"
                onClick={() => moveUp(todo.id)}
                disabled={index === 0}
              >
                Up
              </button>
              <button
                type="button"
                onClick={() => moveDown(todo.id)}
                disabled={index === todos.length - 1}
              >
                Down
              </button>
              <button type="button" onClick={() => deleteTodo(todo.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  errors: Record<string, string>;
}

export function useUserProfiles(userIds: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(userIds.length > 0);

  useEffect(() => {
    if (userIds.length === 0) {
      setProfiles({});
      setErrors({});
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);

    Promise.all(
      userIds.map(async (id) => {
        try {
          const response = await fetch(`/api/users/${id}`);
          if (!response.ok) {
            throw new Error(`Failed to load user ${id}: ${response.status}`);
          }
          const user = (await response.json()) as User;
          return { id, user, error: null as string | null };
        } catch (err) {
          const message = err instanceof Error ? err.message : `Failed to load user ${id}`;
          return { id, user: null as User | null, error: message };
        }
      })
    ).then((results) => {
      if (cancelled) return;

      const nextProfiles: Record<string, User> = {};
      const nextErrors: Record<string, string> = {};
      for (const result of results) {
        if (result.user) {
          nextProfiles[result.id] = result.user;
        } else if (result.error) {
          nextErrors[result.id] = result.error;
        }
      }

      setProfiles(nextProfiles);
      setErrors(nextErrors);
      setLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [userIds.join(",")]);

  return { profiles, loading, errors };
}

