import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  error: Error | null;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

export function useUserProfiles(userIds: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [loading, setLoading] = useState(userIds.length > 0);
  const [error, setError] = useState<Error | null>(null);

  const idsKey = userIds.join(",");

  useEffect(() => {
    const ids = idsKey.split(",").filter(Boolean);

    if (ids.length === 0) {
      setProfiles({});
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    Promise.all(
      ids.map(async (id) => {
        const response = await fetch(`/api/users/${id}`);
        if (!response.ok) {
          throw new Error(`Failed to load user ${id}: ${response.status}`);
        }
        const userPayload: unknown = await response.json();
        if (!isUser(userPayload)) {
          throw new Error(`Malformed user data for ${id}`);
        }
        return userPayload;
      }),
    )
      .then((users) => {
        if (cancelled) return;
        const byId: Record<string, User> = {};
        for (const user of users) {
          byId[user.id] = user;
        }
        setProfiles(byId);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err : new Error("Failed to load user profiles"));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [idsKey]);

  return { profiles, loading, error };
}

