import { useEffect, useState } from "react";
import type { UserProfile } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, UserProfile>;
  errors: Record<string, string>;
  loading: boolean;
}

function isUserProfile(value: unknown): value is UserProfile {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, UserProfile>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(ids.length > 0);

  const idsKey = ids.join(",");

  useEffect(() => {
    const currentIds = idsKey.length > 0 ? idsKey.split(",") : [];
    if (currentIds.length === 0) {
      setProfiles({});
      setErrors({});
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setProfiles({});
    setErrors({});

    Promise.all(
      currentIds.map(async (id) => {
        try {
          const response = await fetch(`/api/users/${id}`, {
            signal: controller.signal,
          });
          if (!response.ok) {
            throw new Error(`Failed to load user ${id}: ${response.status}`);
          }
          const rawProfile: unknown = await response.json();
          if (!isUserProfile(rawProfile)) {
            throw new Error(`Malformed profile data for user ${id}`);
          }
          setProfiles((prev) => ({ ...prev, [id]: rawProfile }));
        } catch (err) {
          if (controller.signal.aborted) return;
          const message =
            err instanceof Error ? err.message : `Failed to load user ${id}`;
          setErrors((prev) => ({ ...prev, [id]: message }));
        }
      })
    ).then(() => {
      if (!controller.signal.aborted) {
        setLoading(false);
      }
    });

    return () => controller.abort();
  }, [idsKey]);

  return { profiles, errors, loading };
}

