    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo
      )
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function cancelEditing() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEditing() {
    if (editingId === null) return;
    const text = editingText.trim();
    if (!text) {
      cancelEditing();
      return;
    }
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === editingId ? { ...todo, text } : todo
      )
    );
    cancelEditing();
  }

  function moveTodo(id: string, direction: -1 | 1) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      const target = index + direction;
      if (index === -1 || target < 0 || target >= prev.length) return prev;
      const next = [...prev];
      [next[index], next[target]] = [next[target], next[index]];
      return next;
    });
  }

  return (
    <div>
      <h1>Todo Board</h1>

      <form onSubmit={addTodo}>
        <input
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          placeholder="Add a task"
          aria-label="New task"
        />
        <button type="submit">Add</button>
      </form>

      <div role="group" aria-label="Filter todos">
        <button
          type="button"
          disabled={filter === "all"}
          onClick={() => setFilter("all")}
        >
          All
        </button>
        <button
          type="button"
          disabled={filter === "active"}
          onClick={() => setFilter("active")}
        >
          Active
        </button>
        <button
          type="button"
          disabled={filter === "done"}
          onClick={() => setFilter("done")}
        >
          Done
        </button>
      </div>

      <p>
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>

      <ul>
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((t) => t.id === todo.id);
          const isEditing = editingId === todo.id;

          return (
            <li key={todo.id}>
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleTodo(todo.id)}
                aria-label={`Mark "${todo.text}" as ${
                  todo.done ? "active" : "done"
                }`}
              />

              {isEditing ? (
                <>
                  <input
                    value={editingText}
                    onChange={(e) => setEditingText(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") commitEditing();
                      if (e.key === "Escape") cancelEditing();
                    }}
                    autoFocus
                    aria-label="Edit task text"
                  />
                  <button type="button" onClick={commitEditing}>
                    Save
                  </button>
                  <button type="button" onClick={cancelEditing}>
                    Cancel
                  </button>
                </>
              ) : (
                <>
                  <span
                    style={{
                      textDecoration: todo.done ? "line-through" : "none",
                    }}
                  >
                    {todo.text}
                  </span>
                  <button type="button" onClick={() => startEditing(todo)}>
                    Edit
                  </button>
                </>
              )}

              <button
                type="button"
                onClick={() => moveTodo(todo.id, -1)}
                disabled={index <= 0}
                aria-label={`Move "${todo.text}" up`}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveTodo(todo.id, 1)}
                disabled={index === -1 || index >= todos.length - 1}
                aria-label={`Move "${todo.text}" down`}
              >
                ↓
              </button>

              <button type="button" onClick={() => deleteTodo(todo.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  isLoading: boolean;
  error: string | null;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [isLoading, setIsLoading] = useState(ids.length > 0);
  const [error, setError] = useState<string | null>(null);

  const key = ids.join(",");

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setIsLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setIsLoading(true);
    setError(null);

    Promise.all(
      ids.map(async (id) => {
        const response = await fetch(`/api/users/${id}`);
        if (!response.ok) {
          throw new Error(`Failed to load user ${id}: ${response.status}`);
        }
        const data: unknown = await response.json();
        if (!isUser(data)) {
          throw new Error(`Malformed user data for ${id}`);
        }
        return data;
      }),
    )
      .then((users) => {
        if (cancelled) return;
        const byId: Record<string, User> = {};
        for (const user of users) {
          byId[user.id] = user;
        }
        setProfiles(byId);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to load profiles");
      })
      .finally(() => {
        if (cancelled) return;
        setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [key, ids]);

  return { profiles, isLoading, error };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  const handleReset = () => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  };

  const handleSave = async () => {
    setIsSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="profile-editor">
      <img src={user.avatarUrl} alt={`${displayName}'s avatar`} className="profile-editor__avatar" />

      <label className="profile-editor__field">
        Display name
        <input
          type="text"
          value={displayName}
          onChange={(e) => setDisplayName(e.target.value)}
          disabled={isSaving}
        />
      </label>

      <label className="profile-editor__field">
        Bio
        <textarea
          value={bio}
          onChange={(e) => setBio(e.target.value)}
          disabled={isSaving}
        />
      </label>

      <p className="profile-editor__status">
        {hasChanges ? "Unsaved changes" : "No changes"}
      </p>

      {error && <p className="profile-editor__error" role="alert">{error}</p>}

      <div className="profile-editor__actions">
        <button type="button" onClick={handleReset} disabled={isSaving || !hasChanges}>
          Reset
        </button>
        <button type="button" onClick={handleSave} disabled={isSaving || !hasChanges}>
          {isSaving ? "Saving..." : "Save"}
        </button>
      </div>
    </div>
  );
}

