                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)
                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(viewModel.isRunning && viewModel.elapsed == 0)
            }
            .buttonStyle(.bordered)

            List {
                ForEach(Array(viewModel.laps.enumerated().reversed()), id: \.offset) { index, lapTime in
                    let previous = index > 0 ? viewModel.laps[index - 1] : 0
                    HStack {
                        Text("Lap \(index + 1)")
                            .foregroundStyle(.secondary)
                        Spacer()
                        Text(StopwatchViewModel.formatted(lapTime - previous))
