@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = ""
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading: Bool = false
    @Published private(set) var errorMessage: String?

    private var cancellables = Set<AnyCancellable>()
    private var searchTask: Task<Void, Never>?
    private let session: URLSession

    init(session: URLSession = .shared) {
        self.session = session

        $query
            .removeDuplicates()
            .debounce(for: .milliseconds(300), scheduler: DispatchQueue.main)
            .sink { [weak self] value in
                self?.search(for: value)
            }
            .store(in: &cancellables)
    }

    private func search(for query: String) {
        searchTask?.cancel()

        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            isLoading = false
            errorMessage = nil
            results = []
            return
        }

        searchTask = Task { [weak self] in
            guard let self else { return }
            isLoading = true
            errorMessage = nil

            do {
                let results = try await fetchResults(query: trimmed)
                guard !Task.isCancelled else { return }
                self.results = results
                self.isLoading = false
            } catch is CancellationError {
                // A newer query superseded this one; leave state untouched.
            } catch {
                guard !Task.isCancelled else { return }
                self.results = []
                self.errorMessage = error.localizedDescription
                self.isLoading = false
            }
        }
    }

    deinit {
        searchTask?.cancel()
    }

    private func fetchResults(query: String) async throws -> [SearchResult] {
        guard var components = URLComponents(string: "https://api.example.com/search") else {
            throw URLError(.badURL)
        }
        components.queryItems = [URLQueryItem(name: "q", value: query)]
        guard let url = components.url else {
            throw URLError(.badURL)
        }

        let (data, response) = try await session.data(from: url)
        try Task.checkCancellation()

        guard let httpResponse = response as? HTTPURLResponse,
              (200..<300).contains(httpResponse.statusCode) else {
            throw URLError(.badServerResponse)
        }

        return try JSONDecoder().decode([SearchResult].self, from: data)
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 0) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .padding()

            content
        }
        .frame(minWidth: 320, minHeight: 400)
    }

    @ViewBuilder
    private var content: some View {
        let trimmedQuery = viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines)

        if viewModel.isLoading {
            ProgressView("Searching…")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if let errorMessage = viewModel.errorMessage {
            VStack(spacing: 8) {
                Image(systemName: "exclamationmark.triangle")
                    .foregroundStyle(.secondary)
                Text(errorMessage)
                    .multilineTextAlignment(.center)
                    .foregroundStyle(.secondary)
            }
            .padding()
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if trimmedQuery.isEmpty {
            Text("Start typing to search")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if viewModel.results.isEmpty {
            Text("No results")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            List(viewModel.results) { result in
                VStack(alignment: .leading, spacing: 4) {
                    Text(result.title)
                        .font(.headline)
                    Text(result.subtitle)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }
            .listStyle(.plain)
        }
    }
}

import Foundation
import SwiftUI

struct Lap: Identifiable {
    let id = UUID()
    let number: Int
    let splitTime: TimeInterval
    let totalTime: TimeInterval
}

@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startDate: Date?
    private var accumulated: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startDate = Date()
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            guard let self else { return }
            Task { @MainActor in
                self.tick()
            }
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        accumulated = elapsed
        startDate = nil
    }

    func reset() {
        stop()
        elapsed = 0
        accumulated = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        let previousTotal = laps.first?.totalTime ?? 0
        let split = elapsed - previousTotal
        laps.insert(Lap(number: laps.count + 1, splitTime: split, totalTime: elapsed), at: 0)
    }

    private func tick() {
        guard let startDate else { return }
        elapsed = accumulated + Date().timeIntervalSince(startDate)
    }

    static func format(_ time: TimeInterval) -> String {
        let minutes = Int(time) / 60
        let seconds = Int(time) % 60
        let centiseconds = Int((time.truncatingRemainder(dividingBy: 1)) * 100)
        return String(format: "%02d:%02d.%02d", minutes, seconds, centiseconds)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(StopwatchViewModel.format(viewModel.elapsed))
                .font(.system(size: 56, weight: .semibold, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    viewModel.isRunning ? viewModel.stop() : viewModel.start()
                }
                .buttonStyle(.borderedProminent)
                .tint(viewModel.isRunning ? .red : .green)

                Button("Lap") {
                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)

                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(viewModel.isRunning && viewModel.elapsed == 0)
            }
            .buttonStyle(.bordered)

            List(viewModel.laps) { lap in
                HStack {
                    Text("Lap \(lap.number)")
                        .font(.headline)
                    Spacer()
                    Text(StopwatchViewModel.format(lap.splitTime))
                        .font(.system(.body, design: .monospaced))
                    Spacer()
                    Text(StopwatchViewModel.format(lap.totalTime))
                        .font(.system(.body, design: .monospaced))
                        .foregroundStyle(.secondary)
                }
            }
        }
        .padding()
        .frame(minWidth: 320, minHeight: 400)
    }
}

