import Foundation
import SwiftUI

enum AppTheme: String, CaseIterable, Identifiable, Equatable {
    case system
    case light
    case dark

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .system: return "System"
        case .light: return "Light"
        case .dark: return "Dark"
        }
    }
}

@MainActor
final class SettingsStore: ObservableObject {
    @Published var displayName: String {
        didSet { save() }
    }
    @Published var theme: AppTheme {
        didSet { save() }
    }
    @Published var notificationsEnabled: Bool {
        didSet { save() }
    }
    @Published var refreshInterval: Double {
        didSet { save() }
    }

    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    private let defaults: UserDefaults
    // Suppresses re-writing values we just read back in from an external change notification.
    private var isApplyingExternalChange = false
    private var notificationObserver: NSObjectProtocol?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.displayName = defaults.string(forKey: Keys.displayName) ?? ""
        self.theme = AppTheme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        self.notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        self.refreshInterval = defaults.object(forKey: Keys.refreshInterval) as? Double ?? 60

        notificationObserver = NotificationCenter.default.addObserver(
            forName: UserDefaults.didChangeNotification,
            object: defaults,
            queue: .main
        ) { [weak self] _ in
            // queue: .main guarantees this runs on the main thread synchronously.
            MainActor.assumeIsolated {
                self?.reloadFromDefaults()
            }
        }
    }

    deinit {
        if let notificationObserver {
            NotificationCenter.default.removeObserver(notificationObserver)
        }
    }

    private func save() {
        guard !isApplyingExternalChange else { return }
        defaults.set(displayName, forKey: Keys.displayName)
        defaults.set(theme.rawValue, forKey: Keys.theme)
        defaults.set(notificationsEnabled, forKey: Keys.notificationsEnabled)
        defaults.set(refreshInterval, forKey: Keys.refreshInterval)
    }

    private func reloadFromDefaults() {
        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        let newTheme = AppTheme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        let newRefreshInterval = defaults.object(forKey: Keys.refreshInterval) as? Double ?? 60

        guard newDisplayName != displayName
            || newTheme != theme
            || newNotificationsEnabled != notificationsEnabled
            || newRefreshInterval != refreshInterval
        else { return }

        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        if displayName != newDisplayName { displayName = newDisplayName }
        if theme != newTheme { theme = newTheme }
        if notificationsEnabled != newNotificationsEnabled { notificationsEnabled = newNotificationsEnabled }
        if refreshInterval != newRefreshInterval { refreshInterval = newRefreshInterval }
    }
}

