import Foundation
import SwiftUI

struct ChatMessage: Identifiable, Codable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatViewModel: ObservableObject {
    @Published var messages: [ChatMessage] = []
    @Published var draftText: String = ""

    private let url: URL = {
        guard let url = URL(string: "wss://chat.example.com/room") else {
            preconditionFailure("Invalid chat room URL")
        }
        return url
    }()
    private let session = URLSession(configuration: .default)
    private var webSocketTask: URLSessionWebSocketTask?
    private var reconnectTask: Task<Void, Never>?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var isStopped = false

    func start() {
        isStopped = false
        connect()
    }

    func stop() {
        isStopped = true
        reconnectTask?.cancel()
        reconnectTask = nil
        webSocketTask?.cancel(with: .goingAway, reason: nil)
        webSocketTask = nil
    }

    private func connect() {
        reconnectTask = nil
        let task = session.webSocketTask(with: url)
        webSocketTask = task
        task.resume()
        reconnectDelay = 1
        receiveNext()
    }

    private func receiveNext() {
        webSocketTask?.receive { [weak self] result in
            Task { @MainActor [weak self] in
                guard let self else { return }
                switch result {
                case .success(let message):
                    self.handle(message)
                    self.receiveNext()
                case .failure:
                    self.scheduleReconnect()
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data?
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = text.data(using: .utf8)
        @unknown default:
            data = nil
        }
        guard let data, let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
    }

    private func scheduleReconnect() {
        guard !isStopped, reconnectTask == nil else { return }
        webSocketTask = nil
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        reconnectTask = Task { [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard let self, !Task.isCancelled else { return }
            if !self.isStopped {
                self.connect()
            }
        }
    }

    func sendDraft() {
        let trimmed = draftText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task = webSocketTask else { return }
        let outgoing = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(outgoing) else { return }
        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor [weak self] in
                self?.scheduleReconnect()
            }
        }
        messages.append(outgoing)
        draftText = ""
    }
}

struct ChatScreen: View {
    @StateObject private var viewModel = ChatViewModel()

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(viewModel.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .padding()
                }
                .onChange(of: viewModel.messages) { _ in
                    scrollToBottom(proxy: proxy)
                }
                .onAppear {
                    scrollToBottom(proxy: proxy)
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $viewModel.draftText)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit { viewModel.sendDraft() }
                Button("Send") { viewModel.sendDraft() }
                    .disabled(viewModel.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { viewModel.start() }
        .onDisappear { viewModel.stop() }
    }

    private func scrollToBottom(proxy: ScrollViewProxy) {
        guard let lastId = viewModel.messages.last?.id else { return }
        withAnimation {
            proxy.scrollTo(lastId, anchor: .bottom)
        }
    }
}

import Foundation

// MARK: - Legacy callback-based SDK (stubs)

final class LegacyGeocoder {
    func geocode(_ address: String, completion: @escaping (Result<(Double, Double), Error>) -> Void) {
        completion(.success((0, 0)))
    }
}

final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    func start(file: URL) {
        onProgress?(1.0)
        onFinish?(nil)
    }
}

// MARK: - Continuation bridge

/// Resumes a `CheckedContinuation` exactly once, whichever comes first: the
/// legacy callback firing, or the surrounding `Task` being cancelled. This
/// keeps repeated legacy callbacks or a callback racing a cancellation from
/// triggering a "continuation resumed twice" crash.
private final class SingleResumeContinuation<T>: @unchecked Sendable {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<T, Error>?

    func set(_ continuation: CheckedContinuation<T, Error>) {
        lock.lock()
        self.continuation = continuation
        lock.unlock()
    }

    func resume(with result: Result<T, Error>) {
        lock.lock()
        let pending = continuation
        continuation = nil
        lock.unlock()

        guard let pending else { return }
        switch result {
        case .success(let value): pending.resume(returning: value)
        case .failure(let error): pending.resume(throwing: error)
        }
    }
}

private func withCancellableContinuation<T>(
    _ body: (SingleResumeContinuation<T>) -> Void
) async throws -> T {
    let box = SingleResumeContinuation<T>()
    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
            box.set(continuation)
            body(box)
        }
    } onCancel: {
        box.resume(with: .failure(CancellationError()))
    }
}

// MARK: - Modern async/await wrappers

final class Geocoder {
    private let legacyGeocoder: LegacyGeocoder

    init(legacyGeocoder: LegacyGeocoder = LegacyGeocoder()) {
        self.legacyGeocoder = legacyGeocoder
    }

    func geocode(_ address: String) async throws -> (Double, Double) {
        try await withCancellableContinuation { box in
            legacyGeocoder.geocode(address) { result in
                box.resume(with: result)
            }
        }
    }
}

final class Uploader {
    enum UploadError: Error {
        case alreadyInProgress
    }

    private let legacyUploader: LegacyUploader
    private let lock = NSLock()
    private var progressContinuation: AsyncStream<Double>.Continuation?
    private var isUploading = false

    private(set) var progressStream: AsyncStream<Double>

    init(legacyUploader: LegacyUploader = LegacyUploader()) {
        self.legacyUploader = legacyUploader
        let (stream, continuation) = AsyncStream<Double>.makeStream()
        continuation.finish()
        self.progressStream = stream
    }

    func upload(file: URL) async throws {
        try lock.withLock {
            guard !isUploading else {
                throw UploadError.alreadyInProgress
            }
            isUploading = true
            let (stream, continuation) = AsyncStream<Double>.makeStream()
            progressStream = stream
            progressContinuation = continuation
        }

        defer {
            lock.withLock { isUploading = false }
        }

        try await withCancellableContinuation { (box: SingleResumeContinuation<Void>) in
            legacyUploader.onProgress = { [weak self] progress in
                self?.progressContinuation?.yield(progress)
            }
            legacyUploader.onFinish = { [weak self] error in
                self?.progressContinuation?.finish()
                box.resume(with: error.map { .failure($0) } ?? .success(()))
            }
            legacyUploader.start(file: file)
        }
    }
}

import SwiftUI
import Combine
import Foundation

struct ChatMessage: Identifiable, Codable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published private(set) var isConnected = false

    private static let url: URL = {
        guard let url = URL(string: "wss://chat.example.com/room") else {
            preconditionFailure("Invalid chat room URL")
        }
        return url
    }()
    private let session = URLSession(configuration: .default)
    private var task: URLSessionWebSocketTask?
    private var reconnectAttempt = 0
    private var isStopped = true

    func start() {
        guard isStopped else { return }
        isStopped = false
        connect()
    }

    func stop() {
        isStopped = true
        task?.cancel(with: .normalClosure, reason: nil)
        task = nil
        isConnected = false
    }

    private func connect() {
        let newTask = session.webSocketTask(with: Self.url)
        task = newTask
        isConnected = true
        reconnectAttempt = 0
        newTask.resume()
        listen(on: newTask)
    }

    private func listen(on task: URLSessionWebSocketTask) {
        task.receive { [weak self] result in
            Task { @MainActor [weak self] in
                guard let self else { return }
                switch result {
                case .failure:
                    self.handleDisconnect()
                case .success(let message):
                    self.handle(message)
                    self.listen(on: task)
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data?
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = text.data(using: .utf8)
        @unknown default:
            data = nil
        }
        guard let data, let decoded = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(decoded)
    }

    func send(author: String, text: String) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task else { return }
        let outgoing = ChatMessage(id: UUID().uuidString, author: author, text: trimmed)
        guard let data = try? JSONEncoder().encode(outgoing) else { return }
        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor [weak self] in
                self?.handleDisconnect()
            }
        }
    }

    private func handleDisconnect() {
        guard !isStopped else { return }
        isConnected = false
        task = nil
        reconnectAttempt += 1
        let delaySeconds = min(30.0, pow(2.0, Double(reconnectAttempt)))
        Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(delaySeconds * 1_000_000_000))
            guard let self, !self.isStopped else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var connection = ChatConnection()
    @State private var draft = ""

    private let currentAuthor = "me"

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(connection.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .id(message.id)
                        }
                    }
                    .padding()
                }
                .onChange(of: connection.messages) { newValue in
                    guard let last = newValue.last else { return }
                    withAnimation {
                        proxy.scrollTo(last.id, anchor: .bottom)
                    }
                }
                .onAppear {
                    if let last = connection.messages.last {
                        proxy.scrollTo(last.id, anchor: .bottom)
                    }
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit(sendDraft)
                Button("Send", action: sendDraft)
                    .disabled(draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .task {
            connection.start()
        }
        .onDisappear {
            connection.stop()
        }
    }

    private func sendDraft() {
        connection.send(author: currentAuthor, text: draft)
        draft = ""
    }
}
